--liquibase formatted sql

-- Seed rows for a scratch dev database. Nothing in the service reads this table yet, so
-- these are sample products only - not reference data any code may assume exists.
--
-- id is left to the identity column rather than written out as 1..10: handing H2 explicit
-- values for a GENERATED BY DEFAULT AS IDENTITY column does not advance its sequence, so a
-- later insert that does let the column generate would collide on the primary key. The
-- rollback therefore deletes by name, which is also why the names have to stay unique.

--changeset stefanbanu:002-insert-products
--rollback DELETE FROM product WHERE name IN ('Mechanical Keyboard', 'Wireless Mouse', '27-inch Monitor', 'USB-C Docking Station', 'Noise-Cancelling Headset', '1TB NVMe SSD', 'Laptop Stand', '1080p Webcam', 'Desk Microphone', 'Surge-Protected Power Strip');
